local config = {
  ui_story_30980101_1_dialog_content = "(\"Apa pun yang terjadi, aku tidak akan pernah bisa mundur.\")",
  ui_story_30980101_2_dialog_content = "(Apakah itu cara yang tepat untuk melihat masa laluku...?)",
  ui_story_30980101_3_dialog_content = "Jadi, alasanmu datang mencariku sepagi ini adalah...",
  ui_story_30980101_4_dialog_content = "Sejujurnya: Adakah sesuatu yang kamu sembunyikan dariku?",
  ui_story_30980101_5_dialog_content = "Mengapa kamu bertanya?",
  ui_story_30980101_6_dialog_content = [[
Tidak ada satu pun tempat yang lembap di Colossus ini, tetapi dari bau rambut dan pakaianmu seolah-olah kamu baru saja haiking melewati hutan. Belum lagi, ini sudah pagi, 
tetapi kamu terlihat sangat lelah...]],
  ui_story_30980101_7_dialog_content = "Kamu baru saja kembali dari suatu tempat?",
  ui_story_30980101_8_dialog_content = "Jadi, kamu menginterogasiku.",
  ui_story_30980101_9_dialog_content = "Aku terlihat seperti orang semacam itu bagimu?! Pakaianmu jelas basah oleh embun pagi...",
  ui_story_30980101_10_dialog_content = "Selain itu, aku melihatmu meninggalkan Colossus dengan tergesa-gesa semalam.",
  ui_story_30980101_11_dialog_content = "Sejujurnya, aku sering melihatmu pergi tengah malam akhir-akhir ini.",
  ui_story_30980101_12_dialog_content = "...",
  ui_story_30980101_13_dialog_content = "Kamu pergi ke mana saja sampai-sampai perlu menyelinap keluar sepanjang malam?",
  ui_story_30980101_14_dialog_content = "Aku tidak pernah mengkhianati siapa pun, jika itu yang kamu siratkan...",
  ui_story_30980101_15_dialog_content = "Aku... Sama sekali bukan itu maksudku.",
  ui_story_30980101_16_dialog_content = "Namun, karena kamu sangat ingin tahu...",
  ui_story_30980101_17_dialog_content = "Mungkin aku membutuhkanmu nanti... Jadi, ikutlah denganku.",
  ui_story_30980101_18_option_content = "A-apa?! Tidak apa-apakah...?",
  ui_story_30980101_19_dialog_content = "Tentu, tetapi... Apakah kamu keberatan jika membawa beberapa kuntum bunga?",
  ui_story_30980101_20_option_content = "Aku tidak mau mengganggumu jika itu adalah hal yang pribadi...",
  ui_story_30980101_21_dialog_content = "Sejujurnya bagiku itu tidak ada bedanya.",
  ui_story_30980101_22_dialog_content = "Kamu hanya perlu membawa beberapa kuntum bunga.",
  ui_story_30980101_23_dialog_content = "Tidak apa, tetapi...",
  ui_story_30980101_24_dialog_content = "Hah? Ke mana dia pergi?!",
  ui_story_30980101_25_dialog_content = "Kamu membuatku menunggu lama.",
  ui_story_30980101_26_dialog_content = "Maaf! Aku tidak sadar tempatnya seperti ini, dan aku sedikit tersesat...",
  ui_story_30980101_27_dialog_content = "Apakah ini...",
  ui_story_30980101_28_dialog_content = "Sebuah kuburan.",
  ui_story_30980101_29_dialog_content = "Sebuah kuburan... Aku membaca soal ini di sebuah buku dulu. Kuburan adalah tempat orang-orang pergi untuk berziarah dan mengenang orang-orang yang telah tiada...",
  ui_story_30980101_30_dialog_content = "(Sepertinya aku salah paham padanya...)",
  ui_story_30980101_31_dialog_content = "Apakah kamu memintaku untuk datang menziarahi orang tuamu?",
  ui_story_30980101_32_dialog_content = "...",
  ui_story_30980101_33_dialog_content = "Temanmu?",
  ui_story_30980101_34_dialog_content = "...",
  ui_story_30980101_35_dialog_content = "Salah lagi? Dia tidak berencana MENGUBURKU, 'kan?",
  ui_story_30980101_36_dialog_content = "Ini adalah tempatnya.",
  ui_story_30980101_37_dialog_content = "<color=#e8d9bb>Kami berdiri di depan batu nisan hitam. Batu nisan yang sedikit lebih pendek dari nisan di sekitarnya ini menunjukkan tanda-tanda dibersihkan baru-baru ini dan ada mawar putih segar di depannya.</color>",
  ui_story_30980101_38_dialog_content = "Siapa ini?...",
  ui_story_30980101_39_dialog_content = [[
(Tunggu... Jika kamu melihat lebih dekat pada gambar di batu nisan, selain dari gaya rambut... Orang ini dan Cuscuta 
benar-benar mirip!)]],
  ui_story_30980101_40_dialog_content = "Entahlah. Mungkin itu aku.",
  ui_story_30980101_41_dialog_content = "Oh, begitu, ya... Tunggu, apa?!",
  ui_story_30980101_42_dialog_content = "Maksudku, dia sangat mirip denganmu... Kamu tidak bercanda, 'kan?",
  ui_story_30980101_43_dialog_content = "Kecuali... Apakah itu berarti...?!",
  ui_story_30980101_44_dialog_content = "Dari raut wajahmu, izinkan aku memberi tahu ini tidaklah seperti yang kamu pikirkan.",
  ui_story_30980101_45_dialog_content = "Lihat saja lebih dekat namanya.",
  ui_story_30980101_46_dialog_content = "Oh... <color=#FFB400>Elvia</color>?",
  ui_story_30980101_47_dialog_content = "Jadi, bukan kamu...",
  ui_story_30980101_48_dialog_content = "Itu benar... Atau mungkin... Bisa jadi itu aku.",
  ui_story_30980101_49_dialog_content = "Aku bingung... Kamu benar-benar berdiri di hadapanku, 'kan?!",
  ui_story_30980101_50_dialog_content = "Aku merasa seolah-olah tubuh yang beristirahat di sini entah bagaimana terikat dengan keberadaanku.",
  ui_story_30980101_51_dialog_content = "Elvia... Apakah dia masa laluku...?",
  ui_story_30980101_52_dialog_content = "Aku masih belum paham apa yang kamu katakan. Mengapa kamu mengajakku ke sini?",
  ui_story_30980101_53_dialog_content = "Aku sedang mencari jawaban.",
  ui_story_30980101_54_dialog_content = "Selain itu, sepertinya kamu belum menyadari bahwa aku telah <color=#FFB404>dikutuk dengan keabadian</color>.",
  ui_story_30980101_55_dialog_content = "Keabadian?!",
  ui_story_30980101_56_dialog_content = "Namun, ada banyak Aurorian yang berumur panjang...",
  ui_story_30980101_57_dialog_content = "Kami tidaklah sama. Apa yang mereka miliki adalah umur panjang, tetapi yang aku miliki... Adalah keabadian.",
  ui_story_30980101_58_dialog_content = "Itu adalah kutukanku sejak lahir.",
  ui_story_30980101_59_dialog_content = [[
Aku punya banyak tubuh. Ketika salah satu di antaranya menua dan mendekati ajalnya, aku berganti tubuh 
dan terlahir kembali di tubuh yang baru.]],
  ui_story_30980101_60_dialog_content = "Itu sebabnya aku abadi. Aku tidak pernah benar-benar tahu rasanya kematian.",
  ui_story_30980101_61_option_content = "Namun, jika kamu tidak bisa mati... Bisakah kamu menyebutnya kutukan?",
  ui_story_30980101_62_dialog_content = "Aku rasa kebanyakan orang berharap bisa hidup selamanya.",
  ui_story_30980101_63_dialog_content = "Itukah yang kamu pikirkan? Mungkin kamu benar...",
  ui_story_30980101_64_option_content = "Keabadian juga bisa menyiksa.",
  ui_story_30980101_65_dialog_content = "Penderitaan? Aku juga tidak tahu rasanya... Namun, kamu tampak sedih sekarang.",
  ui_story_30980101_66_dialog_content = "Melihat orang-orang terdekatmu tiada sementara kamu terus hidup selamanya... Itu menyakitkan...",
  ui_story_30980101_67_dialog_content = "Mungkin aku pernah mengalami rasa sakit itu, tetapi aku tidak ingat.",
  ui_story_30980101_68_dialog_content = "Aspek lain dari keabadianku adalah aku tidak memiliki ingatan atau emosi.",
  ui_story_30980101_69_dialog_content = "Seperti saat ini, saat aku melihat batu nisanku sendiri...",
  ui_story_30980101_70_dialog_content = "Aku mencari ingatan tentang \"Elvia\" ini di benakku... Namun, aku tidak bisa mengingat apa pun.",
  ui_story_30980101_71_dialog_content = "Pikirkan baik-baik. Jika aku melihat batu nisanku sendiri, aku tidak akan bereaksi sepertimu saat ini.",
  ui_story_30980101_72_dialog_content = "Jika situasinya seperti yang kamu bilang, mana mungkin ini adalah salah satu tubuh \"mati\" milikmu, 'kan?",
  ui_story_30980101_73_dialog_content = "Aku tidak ingat...",
  ui_story_30980101_74_dialog_content = "Hanya saja, menurutku... Mungkin aku pernah merasakan perpisahan kematian satu kali, dan mungkin... Aku pernah dekat dan merasa sayang kepada seseorang pada suatu waktu...",
  ui_story_30980101_75_dialog_content = "Jika benar demikian, aku bertanya-tanya siapa gerangan dia...",
  ui_story_30980101_76_dialog_content = "Sepertinya... Dialah yang membuat batu nisan ini untukku.",
  ui_story_30980101_77_dialog_content = "Kalau dipikir-pikir, sepertinya batu nisan ini sering dikunjungi.",
  ui_story_30980101_78_dialog_content = "Menurutmu mungkin itu dia?",
  ui_story_30980101_79_dialog_content = "Aku... Aku harap begitu.",
  ui_story_30980101_80_dialog_content = "Sejak aku menemukan kuburan ini, dia selalu datang kira-kira pada waktu ini untuk berziarah dan membersihkannya...",
  ui_story_30980101_81_dialog_content = "Jadi, kamu pernah melihat orang ini?",
  ui_story_30980101_82_dialog_content = "Hanya dari kejauhan, dan hanya dari belakang. Dia pria yang tinggi, dengan rambut putih keperakan dan telinga besar seperti binatang.",
  ui_story_30980101_83_dialog_content = "(Deskripsi itu terdengar tidak asing... Namun, siapakah itu?)",
  ui_story_30980101_84_dialog_content = "Jadi, kamu belum pernah menemuinya untuk menanyakan masa lalumu?",
  ui_story_30980101_85_dialog_content = [[
Aku... Aku takut... Atau setidaknya aku berpikir begitu. Aku benar-benar ingin tahu lebih banyak tentang diriku, tetapi ketika aku berniat untuk bertanya padanya... Dadaku terasa sesak. 
Menurutmu apakah itu yang namanya ketakutan?]],
  ui_story_30980101_86_dialog_content = "Aku paham... Ketakutan adalah respons alami. Setiap Aurorian akan takut ketika berhadapan dengan hal yang tidak diketahui.",
  ui_story_30980101_87_dialog_content = "Kalau begitu, aku seorang Aurorian?",
  ui_story_30980101_88_dialog_content = "Tentu saja! Untuk apa dia datang ke kuburanmu setiap tahun pada hari peringatan kematianmu?",
  ui_story_30980101_89_dialog_content = "... Mengapa rasanya begitu aneh.",
  ui_story_30980101_90_dialog_content = "Setiap kali dia datang, dia meninggalkan karangan bunga <color=#FFB400>mawar putih</color>.",
  ui_story_30980101_91_dialog_content = "Ah... Ini bunga mawar putih...",
  ui_story_30980101_92_dialog_content = "(Mawar putih... Simbol kesucian dan kepolosan? Tidak, mungkin tanda penghormatan...)",
  ui_story_30980101_93_dialog_content = "Seharusnya dia akan segera datang. Aku... Aku ingin bertemu dengannya.",
  ui_story_30980101_94_dialog_content = "Namun...",
  ui_story_30980101_95_dialog_content = "Namun... Seharusnya kamu sudah mati! Jika aku melihat orang mati muncul di depanku...",
  ui_story_30980101_96_dialog_content = "Tidak, tunggu! Argh, ini gila... Apa pun yang kukatakan, sepertinya kamu benar-benar mati...",
  ui_story_30980101_97_dialog_content = "Itu sebabnya aku butuh bantuanmu...",
  ui_story_30980101_98_option_content = "Aku mengerti.",
  ui_story_30980101_99_dialog_content = "Kamu ingin aku menanyakan tentang dirimu di masa lalu kepadanya, 'kan?",
  ui_story_30980101_100_dialog_content = "Kamu tidak keberatan?",
  ui_story_30980101_101_option_content = "Aku masih bingung.",
  ui_story_30980101_102_dialog_content = "Aku ingin kamu mewakiliku untuk bertanya kepadanya soal diriku di masa lalu.",
  ui_story_30980101_103_dialog_content = "Jadi, begitu, ya...",
  ui_story_30980101_104_dialog_content = "Tidak masalah.",
  ui_story_30980101_105_dialog_content = "Namun... Apakah masa lalumu begitu penting? Kamu tampak sangat mencemaskannya...",
  ui_story_30980101_106_dialog_content = "Aku tidak mengkhawatirkan masa laluku... Namun, jika aku bisa memahami pengalaman diriku di masa lalu...",
  ui_story_30980101_107_dialog_content = "Akankah diriku saat ini dapat berpikir seperti diriku di masa lalu?",
  ui_story_30980101_108_dialog_content = "Aku yakin versi masa laluku sangat berbeda dariku saat ini... Mungkin hatinya merasakan lebih banyak hal daripada yang pernah kuharapkan?",
  ui_story_30980101_109_dialog_content = "...",
  ui_story_30980101_110_option_content = "Namun, raut wajahmu menyiratkan bahwa kamu lebih memilih untuk tidak tahu.",
  ui_story_30980101_111_dialog_content = "Apa?",
  ui_story_30980101_112_dialog_content = "Kamu terlihat sangat sedih... Atau mungkin ragu-ragu?",
  ui_story_30980101_113_dialog_content = "Kurasa, dibandingkan dengan diri masa lalu yang sedang kamu bicarakan ini... \"Kamu\" saat ini adalah \"kamu\" yang sebenarnya.",
  ui_story_30980101_114_dialog_content = "Apa aku... Apa raut wajahku menyiratkan begitu?",
  ui_story_30980101_115_dialog_content = "Mungkin aku tidak bisa membaca hati manusia, tetapi aku bisa membaca raut wajah dengan cukup jelas.",
  ui_story_30980101_116_dialog_content = "Entahlah.",
  ui_story_30980101_117_dialog_content = "...",
  ui_story_30980101_118_dialog_content = "Aku tidak tahu apakah ini namanya kesedihan sejati, atau aku hanya merasa sedih dalam situasi ini.",
  ui_story_30980101_119_dialog_content = "Bagaimana bilangnya, ya... Sejujurnya, aku tidak tahu apa pengaruh dari \"kutukan\"-mu itu, Cuscuta...",
  ui_story_30980101_120_dialog_content = "Namun, kamu harus selalu memercayai hatimu.",
  ui_story_30980101_121_dialog_content = "Jika kamu mengetahui masa lalumu tidak terlalu membahagiakan... Bukankah masa depanmu yang paling penting?",
  ui_story_30980101_122_dialog_content = "Masa depanku?",
  ui_story_30980101_123_dialog_content = "Mungkin kamu benar.",
  ui_story_30980101_124_dialog_content = "Dia tidak perlu diyakinkan, bukan?!",
  ui_story_30980101_125_dialog_content = "Terlepas dari apa yang terjadi, pada akhirnya, aku hanya ingin kamu menjalani kehidupan yang baik. Aku akan puas selama kamu tahu rasanya bahagia.",
  ui_story_30980101_126_dialog_content = "Mungkin aku akan merasakannya, selama aku mengikutimu.",
  ui_story_30980101_127_dialog_content = "Hmm? Raut wajahmu... Tampak jauh lebih baik sekarang.",
  ui_story_30980101_128_dialog_content = "Apakah itu caramu mengajakku kencan?",
  ui_story_30980101_129_dialog_content = "A-apa?!?",
  ui_story_30980101_130_dialog_content = "<color=#e8d9bb>Cuscuta meletakkan karangan bunga <color=#FFB400>mawar hitam</color> di batu nisan, tepat di sebelah karangan bunga mawar putih.</color>",
  ui_story_30980101_131_dialog_content = "Kita harus terus menatap ke depan...",
  ui_story_30980101_132_dialog_content = "Hingga hari kita akhirnya terbaring untuk beristirahat.",
  ui_story_30980601_1_dialog_content = "Anda disini.",
  ui_story_30980601_2_dialog_content = "Saya menerima pesan Anda tentang membutuhkan bantuan untuk sesuatu yang mendesak, jadi saya datang secepat mungkin.",
  ui_story_30980601_3_dialog_content = "Pasti sesuatu yang luar biasa jika seseorang setenang dan terkumpul seperti Anda meminta bantuan, Cuscuta.",
  ui_story_30980601_4_dialog_content = "Jadi apa yang sebenarnya terjadi? Apakah kamu terluka?",
  ui_story_30980601_5_dialog_content = "Saya baik-baik saja. Aku hanya menyelidiki sebuah kasus.",
  ui_story_30980601_6_dialog_content = "Tidak heran Anda berpakaian sedikit berbeda dari biasanya!",
  ui_story_30980601_7_dialog_content = "Paman Istvan menugaskan saya untuk menyelidiki serangkaian pembunuhan berantai.",
  ui_story_30980601_8_dialog_content = "<size=45>S-Serial pembunuhan</size>?! Bagaimana hal seperti itu bisa terjadi?",
  ui_story_30980601_9_dialog_content = "Itu adalah karya seorang pembunuh berantai terkenal yang bersembunyi di bayang-bayang Umbraton. Aksi kekerasannya telah merenggut nyawa banyak gadis muda di kota.",
  ui_story_30980601_10_dialog_content = "Jadi kau melacak si pembunuh? Kedengarannya sangat berbahaya!",
  ui_story_30980601_11_dialog_content = "Hanya satu gadis yang pernah selamat dari serangannya. Dia lolos dari kematian baru kemarin dan bahkan melihat wajah si pembunuh.",
  ui_story_30980601_12_dialog_content = "Maka kalian harus melindunginya dengan segala cara! Sudahkah Anda mencoba bertanya kepadanya tentang pembunuhnya?",
  ui_story_30980601_13_dialog_content = "Kami sedang melakukan itu, ya. Hanya saja...",
  ui_story_30980601_14_dialog_content = "Hanya apa?",
  ui_story_30980601_15_dialog_content = "Itu juga alasan saya meminta Anda untuk datang ke sini hari ini. Saya berharap Anda dapat membantu saya dengan penyelidikan saya.",
  ui_story_30980601_16_dialog_content = "Tentu saja! Semakin cepat kita menangkap maniak pembunuh itu, semakin baik!",
  ui_story_30980601_17_dialog_content = "Jika Anda tidak keberatan, bisakah Anda ...",
  ui_story_30980601_18_dialog_content = "Sebutkan saja, saya akan melakukan apa saja untuk membantu!",
  ui_story_30980601_19_dialog_content = "Tolong berdandan sebagai seorang gadis.",
  ui_story_30980601_20_dialog_content = "Ha? <size=45>A A</size> <size=50>gadis</size>?!",
  ui_story_30980601_21_dialog_content = "Benar sekali.",
  ui_story_30980601_22_option_content = "Aku akan pergi mengubah sekarang!",
  ui_story_30980601_23_dialog_content = "Anda langsung setuju... Terima kasih, Caelestite.",
  ui_story_30980601_24_dialog_content = "Aku menyiapkan gaun hanya untukmu. Di Sini.",
  ui_story_30980601_25_dialog_content = "Ini bukan apa-apa! Saya tahu persis mengapa Anda membutuhkan saya untuk melakukan ini.",
  ui_story_30980601_26_option_content = "Bisakah saya bertanya mengapa dulu?",
  ui_story_30980601_27_dialog_content = "B-Bagaimana ini bisa membantu kasus Anda?",
  ui_story_30980601_28_dialog_content = "Tunggu... aku mengerti!",
  ui_story_30980601_29_dialog_content = "Kamu menginginkan aku untuk <size=45>berpura-pura</size> untuk menjadi seorang gadis, sehingga Anda bisa <size=45>menarik</size> pembunuh dan <size=45>menangkap</size> dia!",
  ui_story_30980601_30_dialog_content = "Kedengarannya agak berisiko, tetapi jika itu membantu kita menangkap si pembunuh, itu risiko yang bersedia saya ambil!",
  ui_story_30980601_31_dialog_content = "Ini bukan rencana paling mudah yang pernah saya lihat, tapi saya kira saya adalah orang yang tepat untuk pekerjaan itu... Jadi ayo kita lakukan!",
  ui_story_30980601_32_dialog_content = "Bukan itu.",
  ui_story_30980601_33_dialog_content = "Tunggu apa? Anda tidak membutuhkan saya untuk menarik keluar si pembunuh?",
  ui_story_30980601_34_dialog_content = "Rencana yang Anda sarankan sempurna, tetapi kami belum sampai pada langkah itu.",
  ui_story_30980601_35_dialog_content = "Hehe, terima kasih atas pujiannya. Jadi apa sebenarnya rencananya...?",
  ui_story_30980601_36_dialog_content = "Kita perlu menanyai orang yang selamat untuk mendapatkan petunjuk tentang si pembunuh.",
  ui_story_30980601_37_dialog_content = "Dan apa hubungannya dengan saya berdandan sebagai seorang gadis?",
  ui_story_30980601_38_dialog_content = "Trauma orang yang selamat membuatnya sangat tidak percaya pada pria. Aku satu-satunya yang akan dia ajak bicara sekarang.",
  ui_story_30980601_39_dialog_content = "Sayangnya, saya bukan yang terhebat dalam hal komunikasi, dan saya tidak tahu bagaimana berbicara dengannya.",
  ui_story_30980601_40_dialog_content = "Awalnya, kupikir aku bisa menutup jarak di antara kami hanya dengan duduk bersama dalam diam.",
  ui_story_30980601_41_dialog_content = "Mungkin itu adalah aura terkutuk yang memancar dari tubuhku, dia terlihat lebih ketakutan dari sebelumnya.",
  ui_story_30980601_42_dialog_content = "Saya membutuhkan seseorang dengan keterampilan interpersonal yang sempurna, seseorang yang dapat berteman dengan siapa pun, dan orang pertama yang saya pikirkan adalah Anda.",
  ui_story_30980601_43_dialog_content = "Saya menghargainya dan semuanya, tetapi saya tidak sepenuhnya yakin harus berkata apa kepada seseorang yang juga mengalami trauma semacam itu.",
  ui_story_30980601_44_dialog_content = "...",
  ui_story_30980601_45_dialog_content = "T-Tapi aku akan tetap melakukan yang terbaik!",
  ui_story_30980601_46_dialog_content = "Siapa di sana?!",
  ui_story_30980601_47_dialog_content = "Jangan takut. hanya aku, Cuscuta.",
  ui_story_30980601_48_dialog_content = "A-aku sedang membicarakan orang aneh di sebelahmu itu!",
  ui_story_30980601_49_dialog_content = "(Hah? Apa yang aneh tentangku?! Apakah aku mengenakan gaun ini terbalik atau semacamnya? Aku bahkan akan mengatakan aku terlihat cantik jika kau bertanya padaku.)",
  ui_story_30980601_50_dialog_content = "Ini adalah pasangan saya yang sangat ramah dan baik hati, PlayerName.",
  ui_story_30980601_51_dialog_content = "Hai! Eh, ehem, halo!",
  ui_story_30980601_52_dialog_content = "Apakah kamu laki-laki?",
  ui_story_30980601_53_dialog_content = "Dia melihat menembus diriku! aku minta maaf...",
  ui_story_30980601_54_dialog_content = "Kenapa kamu berpakaian seperti itu? Lagi sibuk apa?!",
  ui_story_30980601_55_dialog_content = "T-Tolong jangan gugup! Saya hanya memakai ini untuk menghindari membuat Anda kesal, saya berjanji saya tidak bermaksud jahat!",
  ui_story_30980601_56_dialog_content = "Harap tenang.",
  ui_story_30980601_57_dialog_content = "aku minta maaf. Aku tahu kalian berdua bermaksud baik, hanya saja sarafku benar-benar tertembak setelah semuanya.",
  ui_story_30980601_58_dialog_content = "Saya membayangkan Anda hanya akan menemukan kedamaian jika kita menangkap pembunuhnya, bukan?",
  ui_story_30980601_59_dialog_content = "Itu benar! Anda harus segera menangkapnya, tidak ada waktu untuk disia-siakan! Bahkan hanya memikirkan dia terlalu banyak ...",
  ui_story_30980601_60_dialog_content = "Kami melakukan segala kemungkinan, tapi kami butuh bantuanmu untuk menemukannya...",
  ui_story_30980601_60X1_dialog_content = "Saya tahu bahwa mengingat kembali trauma Anda itu menyakitkan, tetapi itu akan menyelamatkan Anda dari lebih banyak penderitaan jika Anda dapat mengarahkan kami ke arah yang benar.",
  ui_story_30980601_61_dialog_content = "O-Oke. Samar-samar aku bisa mengingatnya...",
  ui_story_30980601_62_dialog_content = "Baiklah, kami telah mencatat semua yang Anda ceritakan kepada kami.",
  ui_story_30980601_63_dialog_content = "Terima kasih telah memberi kami begitu banyak petunjuk.",
  ui_story_30980601_64_dialog_content = "Tolong berjanjilah padaku bahwa kamu akan menangkap monster itu!",
  ui_story_30980601_65_dialog_content = "Saya berjanji. Aku tidak akan membiarkanmu menjalani hidupmu dalam ketakutan.",
  ui_story_30980601_66_dialog_content = "Terima kasih. Aku menaruh semua kepercayaanku padamu.",
  ui_story_30980601_67_dialog_content = "Hmm? Apa yang kamu lihat?",
  ui_story_30980601_68_dialog_content = "Anda tampak sedikit berbeda sekarang, seperti Anda memahami emosi lebih jelas dari sebelumnya.",
  ui_story_30980601_69_dialog_content = "Saya berjanji. Aku tidak akan membiarkanmu menjalani hidupmu dalam ketakutan.",
  ui_story_30980601_70_dialog_content = "Anda tidak akan mengatakan hal seperti itu jika Anda benar-benar tidak memiliki emosi, Cuscuta.",
  ui_story_30980601_71_dialog_content = "Saya membayangkan itu karena saya telah menggunakan tubuh ini begitu lama sehingga hanya ada sedikit ruang kosong dalam ingatan saya.",
  ui_story_30980601_72_dialog_content = "Namun, saya masih harus banyak belajar dalam hal memahami emosi.",
  ui_story_30980601_73_dialog_content = "Jangan terlalu banyak bertanya pada diri sendiri, Cuscuta. Fakta bahwa Anda cukup perhatian untuk menghibur gadis itu barusan membuktikan bahwa Anda telah menempuh perjalanan jauh.",
  ui_story_30980601_74_dialog_content = "...",
  ui_story_30980601_75_dialog_content = "Berdasarkan petunjuk yang kami kumpulkan, sepertinya pembunuhnya adalah laki-laki muda dan berotot.",
  ui_story_30980601_76_dialog_content = "Korban mengklaim bahwa pakaiannya sangat ternoda minyak. Itu, digabungkan dengan petunjuk yang kukumpulkan di kota sebelumnya—",
  ui_story_30980601_77_dialog_content = "Berarti dia mungkin bekerja di stasiun kereta.",
  ui_story_30980601_78_dialog_content = "Kami tidak punya waktu untuk disia-siakan. Ayo pergi.",
  ui_story_30980601_79_dialog_content = "Tunggu, sepertinya ada yang tidak beres...",
  ui_story_30980601_80_dialog_content = "Pembunuhnya tahu bahwa wajahnya telah terlihat, yang berarti identitasnya kemungkinan besar telah dikompromikan.",
  ui_story_30980601_81_dialog_content = "Jika saya pembunuhnya, saya pasti tidak akan kembali ke pekerjaan saya.",
  ui_story_30980601_82_dialog_content = "Alih-alih... <size=45>Saya akan mengejar orang yang selamat</size>!",
  ui_story_30980601_83_dialog_content = "Saat ini, tujuan terpenting si pembunuh adalah membungkam satu-satunya orang yang pernah melihatnya dan hidup untuk menceritakan kisah itu!",
  ui_story_30980601_84_dialog_content = "Yang perlu kita lakukan hanyalah mengintai rumah korban, dan menunggu seseorang yang cocok dengan deskripsinya muncul.",
  ui_story_30980601_85_dialog_content = "Masuk akal. Ayo lakukan itu.",
  ui_story_30980601_86_dialog_content = "Tetap tersembunyi dan awasi.",
  ui_story_30980601_87_dialog_content = "Sudah larut, tapi masih belum ada tanda-tanda pembunuhnya...",
  ui_story_30980601_88_dialog_content = "Orang itu terlihat mencurigakan.",
  ui_story_30980601_89_dialog_content = "Saya memperhatikan dia juga. Orang itu sudah berjalan di sekitar area untuk sementara waktu sekarang.",
  ui_story_30980601_90_dialog_content = "Dapatkan dia.",
  ui_story_30980601_91_dialog_content = "Aaaaahhhh! Apa yang Anda pikir Anda lakukan? Biarkan aku pergi!",
  ui_story_30980601_92_dialog_content = "Siapa kamu, dan apa yang kamu lakukan di sini?",
  ui_story_30980601_93_dialog_content = "Aku seharusnya menanyakan pertanyaan yang sama padamu! Apa ide besarnya, menyerangku entah dari mana seperti ini?!",
  ui_story_30980601_94_dialog_content = "Anda telah berputar-putar di area yang sama untuk beberapa waktu sekarang. Mengapa?",
  ui_story_30980601_95_dialog_content = "Aku hanya tersesat, itu saja! Saya akan pergi ke First Street untuk mencari teman saya, dan seseorang mengarahkan saya ke arah ini.",
  ui_story_30980601_95X1_dialog_content = "Tetapi ketika saya sampai di sini, saya perhatikan bahwa rambu-rambu jalan semuanya bertuliskan Second Street! Saya telah berkeliling mencoba menemukan jalan saya sejak saat itu.",
  ui_story_30980601_96_dialog_content = "Benarkah?",
  ui_story_30980601_97_dialog_content = "Dia! Lihat, saya punya alamat teman saya di sini!",
  ui_story_30980601_98_dialog_content = "Dia tidak berbohong...",
  ui_story_30980601_99_dialog_content = "Oh tidak! Kami <size=45>jatuh untuk itu</size>!",
  ui_story_30980601_100_dialog_content = "Ah!",
  ui_story_30980601_101_dialog_content = "Anda disana! Kami tahu Anda akan muncul cepat atau lambat, <size=45>pembunuh berantai</size>!",
  ui_story_30980601_102_dialog_content = "Hmph!",
  ui_story_30980601_103_dialog_content = "Jauhkan tanganmu darinya!",
  ui_story_30980601_104_dialog_content = "Urgh—",
  ui_story_30980601_105_dialog_content = "<size=45>Cuscuta</size>!!!",
  ui_story_30980601_106_dialog_content = "Dia tidak bernapas! Apa yang telah terjadi?!",
  ui_story_30980601_107_dialog_content = "Cih! Sudah mati, eh?!",
  ui_story_30980601_108_dialog_content = "Anda <size=45>terbunuh</size> Cuscuta!!!",
  ui_story_30980601_109_dialog_content = "Bwahahaha! Dan selanjutnya adalah <size=45>Anda</size>!",
  ui_story_30980601_110_dialog_content = "<color=#e8d9bb>Mendera!</color>",
  ui_story_30980601_111_dialog_content = "Aduh! Beraninya kau memukulku?!",
  ui_story_30980601_112_dialog_content = "(Orang ini sangat kuat. Aku tidak akan bisa bertahan lama! Aku perlu memikirkan sesuatu...)",
  ui_story_30980601_113_dialog_content = "Aaaaaah! Itu menyakitkan!!!",
  ui_story_30980601_114_dialog_content = "(Hah? Apa yang terjadi padanya?)",
  ui_story_30980601_115_dialog_content = "Ahhhh!",
  ui_story_30980601_116_dialog_content = "Aku tidak bisa bernafas... Tolong... aku...",
  ui_story_30980601_117_dialog_content = "Apakah... Apakah dia <size=45>mati</size>?! Dia tidak bernafas...",
  ui_story_30980601_118_dialog_content = "Cuscuta!",
  ui_story_30980601_119_dialog_content = "Tubuhnya menjadi dingin...",
  ui_story_30980601_120_dialog_content = "Bunga putih bermekaran di sekujur tubuh Cuscuta...",
  ui_story_30980601_121_dialog_content = "Tunggu... Apa itu kutukannya?",
  ui_story_30980601_122_dialog_content = "Kutukan yang keluar dari tubuh Cuscuta mencekik si pembunuh?",
  ui_story_30980601_123_dialog_content = "Oh, benar! Gadis itu!",
  ui_story_30980601_124_dialog_content = "Fiuh... Syukurlah dia baru saja pingsan. Setidaknya salah satu dari mereka masih bernapas.",
  ui_story_30980601_125_dialog_content = "Saya perlu meminta bantuan, dan mengirimnya ke rumah sakit.",
  ui_story_30980601_126_dialog_content = "<size=45>Cuscuta!</size>",
  ui_story_30980601_127_dialog_content = "Ya?",
  ui_story_30980601_128_dialog_content = "kamu <size=45>hidup lagi</size>! Aku sangat lega!",
  ui_story_30980601_129_dialog_content = "Oke.",
  ui_story_30980601_130_dialog_content = "Anda terlihat sedikit aneh, Cuscuta. Rasanya seperti Anda kehilangan sesuatu ...",
  ui_story_30980601_131_dialog_content = "Saya kehilangan sebagian dari ingatan saya setiap kali saya mati dan hidup kembali. Yang saya ingat adalah bahwa saya memiliki misi untuk diselesaikan.",
  ui_story_30980601_131X1_dialog_content = "Itu sebabnya saya datang ke sini tanpa menyadarinya.",
  ui_story_30980601_132_dialog_content = "Tapi Anda berhasil menyelesaikan misi Anda, Cuscuta!",
  ui_story_30980601_133_dialog_content = "Setelah Anda mati, kutukan Anda menyerang si pembunuh. Dia sudah mati sekarang.",
  ui_story_30980601_134_dialog_content = "Oh.",
  ui_story_30980601_135_dialog_content = "Bagaimana dengan gadis itu?",
  ui_story_30980601_136_dialog_content = "Dia sudah bangun sekarang. Dia hampir pingsan lagi saat mengetahui bahwa kamu terluka saat mencoba menyelamatkannya.",
  ui_story_30980601_137_dialog_content = "Oh, benar. Saya hanya mengatakan kepadanya bahwa Anda terluka. Siapa yang tahu bagaimana dia akan bereaksi melihatmu kembali dari kematian?",
  ui_story_30980601_138_dialog_content = "Jadi begitu. Terima kasih.",
  ui_story_30980601_139_dialog_content = "Anda khawatir tentang dia.",
  ui_story_30980601_140_dialog_content = "Hah?",
  ui_story_30980601_141_dialog_content = "Anda mungkin tidak ingat banyak tentang apa yang terjadi, tetapi jelas bahwa Anda menunjukkan kekhawatiran.",
  ui_story_30980601_142_dialog_content = "Apakah kamu tidak melihat? Anda sudah mulai memahami emosi!",
  ui_story_30980601_143_dialog_content = "Tempat apa itu?",
  ui_story_30980601_144_dialog_content = "Apakah Anda ingat apa yang terjadi tepat sebelum Anda meninggal?",
  ui_story_30980601_145_dialog_content = "Tidak ada sama sekali.",
  ui_story_30980601_146_dialog_content = "Anda melompat di antara si pembunuh dan gadis itu dan membawa pisau ke hati, semuanya untuk melindunginya!",
  ui_story_30980601_147_dialog_content = "Itu berarti Anda dapat memahami apa artinya <size=45>mengorbankan diri untuk orang lain</size>. Itu salah satu emosi paling kuat yang bisa dirasakan seseorang!",
  ui_story_30980601_148_dialog_content = "Benar.",
  ui_story_30980601_149_dialog_content = "Tunggu, apakah itu senyuman tadi? Kapan kamu belajar tersenyum, Cuscuta?",
  ui_story_30980601_150_dialog_content = "Entah apa itu senyuman.",
  ui_story_30980601_151_dialog_content = "Itu adalah ekspresi alami yang Anda tunjukkan saat Anda bahagia atau mengakui sesuatu.",
  ui_story_30980601_152_dialog_content = "Itu tidak terlalu terlihat, tetapi saya tahu bahwa Anda baru saja tersenyum, Cuscuta!"
}
